from collections import defaultdict

def map_fn(doc):
    return [(w, 1) for w in doc.split()]

def reduce_fn(key, values):
    return sum(values)

def part(key, R):
    return sum(map(ord, key)) % R   # stand-in for ihash(key) % nReduce

docs = ["the cat sat", "the dog sat", "the end"]
R = 2
buckets = [defaultdict(list) for _ in range(R)]
for d in docs:                                   # map phase
    for k, v in map_fn(d):
        buckets[part(k, R)][k].append(v)
for r, b in enumerate(buckets):                  # reduce phase, keys sorted
    print(r, {k: reduce_fn(k, vs) for k, vs in sorted(b.items())})

