import struct, zlib

def encode(key, val):
    body = f"{key}={val}".encode()
    return struct.pack("<II", len(body), zlib.crc32(body)) + body

def replay(buf):
    state, off = {}, 0
    while off + 8 <= len(buf):
        n, crc = struct.unpack_from("<II", buf, off)
        body = buf[off + 8: off + 8 + n]
        if len(body) < n or zlib.crc32(body) != crc:
            break                      # torn tail: never acknowledged
        k, v = body.decode().split("=", 1)
        state[k] = v
        off += 8 + n
    return state

log = encode("a", "1") + encode("b", "2") + encode("a", "3")
print(replay(log))        # {'a': '3', 'b': '2'}
print(replay(log[:-2]))   # crash mid-append: {'a': '1', 'b': '2'}

def varint(n):
    out = bytearray()
    while True:
        b = n & 0x7F          # low 7 bits
        n >>= 7
        if n:
            out.append(b | 0x80)   # more bytes follow
        else:
            out.append(b)
            return bytes(out)

for n in (1, 127, 128, 300):
    print(n, varint(n).hex())

