func (rf *Raft) RequestVote(args *RequestVoteArgs, reply *RequestVoteReply) {
    rf.mu.Lock()
    defer rf.mu.Unlock()
    if args.Term > rf.currentTerm {
        rf.becomeFollower(args.Term) // sets votedFor = -1 and persists
    }
    reply.Term = rf.currentTerm
    upToDate := args.LastLogTerm > rf.lastLogTerm() ||
        (args.LastLogTerm == rf.lastLogTerm() && args.LastLogIndex >= rf.lastLogIndex())
    if args.Term == rf.currentTerm &&
        (rf.votedFor == -1 || rf.votedFor == args.CandidateId) && upToDate {
        rf.votedFor = args.CandidateId
        rf.persist()            // durable before the reply leaves
        rf.resetElectionTimer() // only reset when the vote is granted
        reply.VoteGranted = true
    }
}

