import time

class CircuitBreaker:
    def __init__(self, threshold=5, cooldown=10.0):
        self.threshold, self.cooldown = threshold, cooldown
        self.failures, self.opened_at = 0, None

    def call(self, fn, fallback):
        if self.opened_at is not None:
            if time.monotonic() - self.opened_at < self.cooldown:
                return fallback()                # open: fail fast
            self.opened_at = None                # half-open: let one call through
        try:
            result = fn()
        except Exception:
            self.failures += 1
            if self.failures >= self.threshold:
                self.opened_at = time.monotonic()  # trip (or re-trip after a failed probe)
            return fallback()
        self.failures = 0                        # success closes the circuit
        return result
